import React, { useEffect, useState } from 'react';
import { tasks as tasksAPI } from '../services/api';
import { auth as authAPI } from '../services/api';
import { removeToken } from '../services/auth';
import { useNavigate } from 'react-router-dom';
import TaskCard from './TaskCard';
import TaskForm from './TaskForm';
import socket from '../services/socket';
import { DragDropContext, Droppable, Draggable } from 'react-beautiful-dnd';

const priorities = ['High', 'Medium', 'Low'];

export default function Dashboard() {
  const [tasks, setTasks] = useState([]);
  const [page, setPage] = useState(1);
  const [limit] = useState(50);
  const [totalPages, setTotalPages] = useState(1);
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState(null);
  const [users, setUsers] = useState([]);
  const nav = useNavigate();

  useEffect(() => {
    fetchTasks();
    fetchUsers();
    socket.connect();
    socket.on('taskCreated', ({ task }) => setTasks((prev) => [task, ...prev]));
    socket.on('taskUpdated', ({ task }) => setTasks((prev) => prev.map((t) => (t._id === task._id ? task : t))));
    socket.on('taskDeleted', ({ id }) => setTasks((prev) => prev.filter((t) => t._id !== id)));
    return () => {
      socket.off('taskCreated');
      socket.off('taskUpdated');
      socket.off('taskDeleted');
      socket.disconnect();
    };
  }, []);

  const fetchTasks = async (p = page) => {
    try {
      const res = await tasksAPI.list(p, limit);
      setTasks(res.data.tasks);
      setPage(res.data.page);
      setTotalPages(res.data.totalPages);
    } catch (err) {
      console.error(err);
      if (err.response?.status === 401) {
        removeToken();
        nav('/login');
      }
    }
  };

  const fetchUsers = async () => {
    // For simplicity: get current user as only available option for assignment
    try {
      const me = await authAPI.me();
      setUsers([me.data]);
    } catch (err) {
      console.error(err);
    }
  };

  const grouped = priorities.reduce((acc, p) => ({ ...acc, [p]: tasks.filter((t) => t.priority === p) }), {});

  const onDragEnd = async (result) => {
    if (!result.destination) return;
    const { source, destination, draggableId } = result;
    const newPriority = destination.droppableId;
    const task = tasks.find((t) => t._id === draggableId);
    if (!task || task.priority === newPriority) return;
    try {
      const res = await tasksAPI.update(draggableId, { priority: newPriority });
      setTasks((prev) => prev.map((t) => (t._id === draggableId ? res.data : t)));
    } catch (err) {
      console.error(err);
    }
  };

  const handleCreate = () => {
    setEditing(null);
    setShowForm(true);
  };

  const handleSubmit = async (data) => {
    try {
      if (editing) {
        await tasksAPI.update(editing._id, data);
      } else {
        await tasksAPI.create(data);
      }
      setShowForm(false);
      fetchTasks(1);
    } catch (err) {
      console.error(err);
    }
  };

  const handleEdit = (task) => {
    setEditing(task);
    setShowForm(true);
  };

  const handleDelete = async (task) => {
    if (!window.confirm('Delete this task?')) return;
    try {
      await tasksAPI.remove(task._id);
      setTasks((prev) => prev.filter((t) => t._id !== task._id));
    } catch (err) {
      console.error(err);
    }
  };

  const toggleStatus = async (task) => {
    try {
      const newStatus = task.status === 'Pending' ? 'Completed' : 'Pending';
      const res = await tasksAPI.update(task._id, { status: newStatus });
      setTasks((prev) => prev.map((t) => (t._id === task._id ? res.data : t)));
    } catch (err) {
      console.error(err);
    }
  };

  const logout = () => {
    removeToken();
    nav('/login');
  };

  return (
    <div className="dashboard">
      <header>
        <h1>Tasks</h1>
        <div>
          <button onClick={handleCreate}>New Task</button>
          <button onClick={logout}>Logout</button>
        </div>
      </header>

      {showForm && (
        <div className="modal">
          <div className="modal-content">
            <h3>{editing ? 'Edit Task' : 'Create Task'}</h3>
            <TaskForm initial={editing || {}} users={users} onSubmit={handleSubmit} onCancel={() => setShowForm(false)} />
          </div>
        </div>
      )}

      <DragDropContext onDragEnd={onDragEnd}>
        <div className="columns">
          {priorities.map((p) => (
            <Droppable droppableId={p} key={p}>
              {(provided) => (
                <div className="column" ref={provided.innerRef} {...provided.droppableProps}>
                  <h2 className={`col-${p.toLowerCase()}`}>{p}</h2>
                  {grouped[p].map((task, idx) => (
                    <Draggable draggableId={task._id} index={idx} key={task._id}>
                      {(prov) => (
                        <div ref={prov.innerRef} {...prov.draggableProps} {...prov.dragHandleProps}>
                          <TaskCard task={task} onEdit={handleEdit} onDelete={handleDelete} onToggleStatus={toggleStatus} />
                        </div>
                      )}
                    </Draggable>
                  ))}
                  {provided.placeholder}
                </div>
              )}
            </Droppable>
          ))}
        </div>
      </DragDropContext>

      <footer className="pagination">
        <button disabled={page <= 1} onClick={() => fetchTasks(page - 1)}>
          Prev
        </button>
        <span>
          Page {page} / {totalPages}
        </span>
        <button disabled={page >= totalPages} onClick={() => fetchTasks(page + 1)}>
          Next
        </button>
      </footer>
    </div>
  );
}
